  document.querySelector('#panel-error').textContent='';const data=new FormData(el),submit=el.querySelector('button:not([data-action])'),original=submit&&submit.textContent;
  const job={cancelled:false,form:el,submit,original,resolve:null,node:null,timer:null,slowTimer:null,timedOut:false};ui.busy=true;ui.waitJob=job;
