    job.slowTimer=setTimeout(()=>{if(!job.cancelled&&node.isConnected)node.querySelector('.wait-message').textContent='准备时间较长，尚未提交。你可以取消等待后重试。';},2600);
    await new Promise(resolve=>{job.resolve=resolve;job.timer=setTimeout(resolve,ms);});
